import{H as i,m as t,q as o,n}from"./index--Tdv9EZP.js";const e={protocols:{name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 52",url:"https://caasanwebsitestorage.blob.core.windows.net/avmed-amended-protocols/Summarised%20Medical%20Protocols%20in%20line%20with%20Part%2067%20of%20the%20Civil%20Aviation%20Regulations%20and%20Technical%20Standards.pdf"},classes:{name:"SACAA: amended Part 67 regulation 67.00.2, classes of medical certificates",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf"},application:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.7 (Application for medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_7_application.php"},class4:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.5 (Class 4 medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_5_class_4_med.php"},cabin:{name:"Civil Aviation Regulations, 2011, Part 64, regulation 64.01.6 (Cabin crew medical fitness)",url:"https://source.acts.co.za/civil-aviation-act-2009/nr425_64_01_6_medical_fit.php"},am007:{name:"SACAA procedure AM007: issuing of Class I, II, III and IV medical certificates (reissued 15 September 2025)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/AM007%20Issuing%20of%20a%20class%20IIIIII%20and%20IV%20medical%20certificate.pdf"},avmed:{name:"SACAA Aviation Medicine page",url:"https://www.caa.co.za/industry-information/aviation-medicine/"},faq:{name:"SACAA Frequently Asked Questions (medical classes and validity periods, Class 4 for cabin crew, who may examine, extensions)",url:"https://www.caa.co.za/information-for-the-public/frequently-asked-questions/"},register:{name:"SACAA list of Regular Designated Aviation Medical Examiners (Dr AO Ndhlovu, MR 336)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Regular%20DAMES.pdf"},form:{name:"SACAA form CA 67-02(a), Aviation Medical Report",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02(a).pdf"},classesReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.2 (Classes of medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_2_classes_of_.php"},designation:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.4 (Designation of aviation medical examiners)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_4_designation.php"},validityReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.6 (Period of validity and extensions)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_6_period_of_v.php"},issuing:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.8 (Issuing of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_8_issuing_of_.php"},duties:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.9 (Duties of holder of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_9_duties_of_h.php"},records:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.12 (Period of validity of medical records)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_12_period_of_.php"},suspension:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.14 (Suspension or cancellation of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_14_suspension.php"},spl:{name:"Civil Aviation Regulations, 2011, Part 61, regulation 61.02.1 (Requirements for SPL or ISPL, as amended 21 August 2026)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_61_02_1_requirements.php"}},s={slug:"renew-sacaa-class-2-medical",title:"How to Renew Your SACAA Class 2 Medical, Step by Step | ClinoTrend",h1:"How to renew your SACAA Class 2 medical, step by step",description:"A practical guide to renewing a SACAA Class 2 aviation medical in South Africa: when to book, which examiner can do it, what to bring, what happens on the day and what to do if it is about to expire.",excerpt:"When to book, which examiner can renew it, what to bring, what happens on the day, and what to do if your certificate is about to expire.",keyword:"class 2 medical renewal",question:"How do I renew my SACAA Class 2 medical?",answer:"Check the expiry date on your certificate, then book a SACAA Designated Aviation Medical Examiner (DAME) a few weeks before it. Bring your ID, licence, current certificate, logbook and a list of your medicines. If you meet the standards, the certificate can be issued at the end of the examination. If time runs out, apply to SACAA for an extension at least 15 days before expiry.",secondary:["sacaa class 2 medical certificate","class 2 medical certificate south africa","sacaa medical extension","sacaa medical examiners"],published:"2026-10-23",updated:"2026-10-29",status:"draft",tag:"Renewals",body:[{t:"p",x:"If you fly on a student pilot licence (SPL) or a private pilot licence (PPL), your licence is only valid while you hold a current Class 2 medical certificate. Renewing it is routine, but a little planning avoids a gap in flying. This guide walks through the renewal in the order you will meet each step, with the South African Civil Aviation Regulations (Part 67) quoted where it matters."},{t:"h2",x:"Who needs a Class 2 medical?",id:"who"},{t:"p",x:"Under the amended regulation 67.00.2 of Part 67, a Class 2 medical certificate covers, among others, the SPL, the PPL for aeroplane, airship and helicopter, the flight engineer licence, the free balloon commercial pilot licence and the commercial glider pilot. The same regulation says that a pilot holding a valid Class 1 certificate is deemed to hold a valid Class 2 and Class 4 certificate."},{t:"p",x:"Cabin crew are now linked to Class 4, not Class 2. If you are cabin crew, read our guide to the [cabin crew Class 4 medical](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"Step 1: check your expiry date",id:"expiry"},{t:"p",x:"Look at the expiry date printed on your current certificate. Certificates run to the **last day of a month**, and SACAA's frequently asked questions list these periods for Class 2:"},{t:"ul",items:["Under 40: 24 months","Over 40: 12 months"]},{t:"p",x:"SACAA notes that the frequency of examinations may also vary depending on medical conditions, so the date on your certificate is the one that counts. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains how the date is counted and has a small expiry calculator."},{t:"h2",x:"Step 2: book with a SACAA designated examiner",id:"examiner"},{t:"p",x:"A Class 2 renewal must be done by a Designated Aviation Medical Examiner (DAME). SACAA designates two kinds. Regular DAMEs may examine for and issue Class II and Class IV certificates. Senior DAMEs may also do Class I and Class III. Your family GP cannot issue a Class 2 certificate unless he or she is designated. Our guide to [SACAA medical examiners](/blog/sacaa-medical-examiners-dame/) shows how to check an examiner on the SACAA list."},{t:"p",x:"SACAA publishes the lists of Regular and Senior DAMEs on its aviation medicine page. It is worth checking that your examiner is on the current list. In 2024 SACAA published a notice asking licence holders who had been examined by an examiner whose designation had lapsed to be examined again, because those certificates were not valid."},{t:"p",x:"Dr A.O. Ndhlovu is listed by SACAA as a Regular DAME, number MR 336, at Grand Central Airport, Gate 2, Midrand. Class 2 renewals are within his scope."},{t:"h3",x:"When to book"},{t:"p",x:"Book a few weeks before your expiry date. That leaves time to get a specialist letter or an extra test if the examiner asks for one, without being grounded while you wait. Keep in mind that the new certificate runs from the month it is issued, so renewing many months early does not add the unused time to the new certificate."},{t:"h2",x:"Step 3: gather your documents",id:"documents"},{t:"p",x:"Regulation 67.00.7 says that when you attend the examination you must show proof of identity, show your licence and your latest medical certificate if you hold one, give the examiner information about your medical history, and sign a declaration that the information on the examination form is accurate, complete and true. In practice, bring:"},{t:"ul",items:["Your South African ID, driving licence or passport","Your pilot licence and your current medical certificate","Your logbook","A list of every medicine you take, including over the counter medicines and supplements","Your glasses or contact lenses, and a recent optometrist prescription if you have one","Your hearing aids, if you use them","Recent reports from your doctor or specialist if anything has changed since your last medical, for example a new diagnosis, an operation or a hospital stay"]},{t:"p",x:"The SACAA form used on the day is the [Aviation Medical Report, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02(a).pdf). Reading it beforehand shows you which history questions you will be asked."},{t:"h2",x:"Step 4: the examination",id:"exam"},{t:"p",x:"A renewal follows the same SACAA standards as your first medical. At ClinoTrend the examination includes your medical history and a physical examination, with these tests done on site:"},{t:"ul",items:["Resting ECG","Vision testing","Hearing test (audiometry)","Urine screening"]},{t:"p",x:"Depending on your age and medical history, the examiner may ask for more, such as blood tests or a lung function test. SACAA's medical requirements table lists a chest X-ray at the initial examination and afterwards only when it is indicated on clinical grounds. If you are likely to need anything extra, we tell you when you book."},{t:"p",x:"Allow about 30 to 60 minutes and arrive 10 minutes early to complete paperwork. Rest well the night before, and avoid heavy caffeine or high sugar meals beforehand, as they can affect some results."},{t:"h2",x:"Step 5: your certificate",id:"certificate"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can be issued at the end of the examination. SACAA procedure AM007 describes two copies with the same serial number: the yellow copy goes to the SACAA licensing department and you keep the white copy with you while flying. Medical restrictions, if any apply, are written on the certificate."},{t:"p",x:"If more information is needed, your assessment is deferred until it arrives. Complicated cases are referred to the SACAA Aeromedical Committee, which AM007 says meets on the third Tuesday of each month, with documents due seven days before the meeting. If you disagree with a decision, Part 67 allows an appeal to the Director of Civil Aviation within 30 days. Read [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) for the full process."},{t:"h2",x:"Running out of time? Extensions",id:"extension"},{t:"p",x:"Part 67, regulation 67.00.6(6), says you must apply for an extension **at least 15 days before your certificate expires**, and that the Director may extend it, on conditions, for **no more than 30 days**. SACAA procedure AM007 also says you must contact the SACAA medical department before the certificate expires, and SACAA's FAQ page explains where to send the request. An extension is a safety net, not a plan, so book your renewal early."},{t:"h2",x:"Renewing at Grand Central Airport",id:"clinotrend"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, Midrand. You can drive in or fly in to FAGC; the apron is outside the Gate 2 terminal doors. Fees are not published on the website; we give you the fee when you book. See the [aviation medicals page](/aviation-medicals/) for how the examination works, and the [contact page](/contact/) for hours and directions."},{t:"cta",x:"Renewal due? Book your Class 2 renewal at Gate 2."}],faq:[{q:"Can my GP renew my Class 2 medical?",a:"Only if your GP is a SACAA Designated Aviation Medical Examiner. Class 1, 2 and 3 applicants must be examined by a DAME. A Class 4 can be done by any HPCSA registered medical practitioner."},{q:"How early can I renew my Class 2 medical?",a:"You can book whenever suits you, but the new certificate is valid from the month it is issued, so time left on the old certificate is not added. Booking a few weeks before expiry leaves time for any extra reports."},{q:"What if my Class 2 medical expires before I can be examined?",a:"Contact the SACAA medical department before the expiry date to ask for an extension, as SACAA procedure AM007 requires. Regulation 67.00.6(6) says to apply at least 15 days before expiry, and an extension is for no more than 30 days. Then book your examination as soon as you can."},{q:"Do I need a chest X-ray for a Class 2 renewal?",a:"SACAA lists a chest X-ray at the initial examination and afterwards only when it is indicated on clinical grounds. We tell you when you book if your renewal needs one."},{q:"Does a Class 1 medical cover Class 2 privileges?",a:"Yes. Regulation 67.00.2 says that a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates."}],sources:[e.faq,e.classes,e.application,e.validityReg,e.am007,e.avmed,e.register,e.form]},r={slug:"cabin-crew-medical-class-4-south-africa",title:"Cabin Crew Medical in South Africa: Class 4 Requirements Explained | ClinoTrend",h1:"Cabin crew medical in South Africa: the Class 4 requirements explained",description:"Which SACAA medical cabin crew need (Class 4), who can do it, what the medical tests involve, how long it is valid and what to bring. Written for cabin crew and cabin crew course entrants.",excerpt:"Which SACAA medical class cabin crew need, who can examine you, what is tested, how long it lasts and what to bring.",keyword:"cabin crew medical requirements",question:"What medical do cabin crew need in South Africa?",answer:"Cabin crew need a SACAA **Class 4** medical certificate. Any HPCSA registered doctor may do the examination, or a SACAA designated examiner. It covers your medical history, a physical examination and tests such as an ECG, vision and hearing. It is valid for 60 months under 40 and 36 months over 40, according to SACAA.",secondary:["cabin crew medical test","cabin crew medical certificate","class 4 medical certificate south africa","cabin crew medical near me"],published:"2026-10-23",updated:"2026-10-29",status:"draft",tag:"Cabin crew",body:[{t:"p",x:"Aviation medicals are not only for pilots. If you work as cabin crew in South Africa, or you are about to start a cabin crew course, you need a valid SACAA medical certificate too. This guide explains which class applies, who can examine you and what to expect on the day."},{t:"h2",x:"Which medical class do cabin crew need?",id:"class"},{t:"p",x:"Part 64 of the Civil Aviation Regulations, which covers cabin crew licensing, says in regulation 64.01.6 that an applicant for or holder of a cabin crew member licence must obtain a medical certificate issued in terms of Part 67. That wording was substituted in March 2019."},{t:"p",x:"The amended Part 67 regulation 67.00.2 then lists the **cabin crew member licence under Class 4**, alongside recreational licences such as microlight, gyroplane and glider. SACAA's frequently asked questions confirm it: the regulation was promulgated in May 2019, cabin crew now require a Class 4 medical, and a DAME should issue a Class 4 certificate."},{t:"confirm",x:"SACAA's aviation medicine page still lists cabin crew under Class II, while the amended regulation and the SACAA FAQ say Class 4. Please confirm which class you issue to cabin crew today."},{t:"note",x:"You may still see cabin crew listed under Class II on SACAA's aviation medicine web page, which predates the change. If an employer or training school asks for a specific class, follow their instruction and tell us when you book, so we issue the right certificate."},{t:"h2",x:"Who can do a cabin crew medical?",id:"who"},{t:"p",x:"Class 4 is the one class that does not have to be done by a designated examiner. Regulation 67.00.5 allows any medical practitioner registered with the HPCSA to perform the examination, provided the application, supporting reports and test results are sent to the designated body within 60 days for verification before the certificate is issued."},{t:"p",x:"A SACAA Designated Aviation Medical Examiner (DAME) can also examine you and issue the certificate. Regular and Senior DAMEs are both authorised for Class IV. Dr A.O. Ndhlovu at ClinoTrend is a Regular DAME (SACAA MR 336), so a cabin crew Class 4 medical is within his scope, at Grand Central Airport in Midrand."},{t:"h2",x:"What does the cabin crew medical test?",id:"tests"},{t:"p",x:"The medical checks that you can safely do the duties of cabin crew, including in an emergency. At ClinoTrend it includes:"},{t:"ul",items:["Your medical history, taken on the SACAA form CA 67-02(a), and a signed declaration","A physical examination","A resting ECG","Vision testing (bring your glasses or contact lenses)","A hearing test (audiometry)","Urine screening"]},{t:"p",x:"Depending on your history, the examiner may ask for more information. The SACAA medical protocols in line with Part 67 describe how some conditions are assessed for cabin crew case by case with a specialist report, for example migraine, a single seizure or a moderate head injury. If you have a condition like this, contact us before your medical so you can bring the right reports and avoid a second visit."},{t:"h3",x:"Medical standards versus airline requirements"},{t:"p",x:"Cabin crew adverts often list height or arm reach ranges, swimming ability, grooming standards and a minimum school qualification. Those are airline or training school requirements, not Part 67 medical standards. The medical certificate covers your medical fitness only. Check the advert or ask the school for its other requirements."},{t:"h2",x:"How long is a cabin crew medical valid?",id:"validity"},{t:"p",x:"SACAA's frequently asked questions list these periods for a Class 4 certificate, which runs to the last day of a month:"},{t:"table",caption:"Class 4 validity (SACAA frequently asked questions)",head:["Your age","Valid for"],rows:[["Under 40","60 months"],["Over 40","36 months"]]},{t:"p",x:"SACAA notes that the frequency of examinations may also vary depending on medical conditions. See [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) for Class 2 periods and an expiry calculator."},{t:"h3",x:"The yearly Class 4 declaration"},{t:"p",x:"Part 67, regulation 67.00.9(3), adds one more duty for Class 4 holders: after the certificate is issued, you must complete and submit a medical declaration to SACAA **every year**, on the form prescribed in SA-CATS 67. Put a yearly reminder in your calendar."},{t:"confirm",x:"Please confirm how your Class 4 patients handle the yearly declaration (which form, and whether the practice helps), so we can add a practical line."},{t:"h2",x:"Starting a cabin crew course?",id:"course"},{t:"p",x:"Because Part 64 requires an applicant for a cabin crew licence to hold a Part 67 medical certificate, you need it before you apply for your licence. Many training schools ask for it at the start of the course, so ask your school when they want it. Getting it done early also tells you about anything that needs attention, such as an eyesight prescription, before you have paid course fees."},{t:"h2",x:"What to bring",id:"bring"},{t:"ul",items:["Your South African ID or passport","Your cabin crew licence and your current medical certificate, if you have them","Your glasses or contact lenses, and your hearing aids if you use them","A list of the medicines you take, including over the counter medicines","Reports from your doctor or specialist for any medical condition","Any form or letter from your employer or training school"]},{t:"h2",x:"Booking your cabin crew medical in Midrand",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, between Johannesburg and Pretoria, and about 5 minutes from Midrand Gautrain Station by e-hailing or taxi. Allow 30 to 60 minutes. Fees are given when you book. Read more on the [aviation medicals page](/aviation-medicals/), or see the [contact page](/contact/) for hours and directions."},{t:"cta",x:"Cabin crew or course entrant? Book your Class 4 medical."}],faq:[{q:"Do cabin crew need a Class 2 or a Class 4 medical?",a:"Class 4. The amended Part 67 regulation 67.00.2 lists the cabin crew member licence under Class 4, and SACAA confirms that cabin crew have needed a Class 4 medical since May 2019."},{q:"Can my own GP do my cabin crew medical?",a:"Yes, if he or she is registered with the HPCSA and follows the Part 67 requirements, sending the application and results for verification within 60 days. A SACAA designated examiner, such as Dr Ndhlovu (MR 336), can also do it."},{q:"How long is a cabin crew medical valid?",a:"SACAA lists 60 months under 40 and 36 months over 40 for a Class 4 certificate. Medical conditions can mean more frequent examinations."},{q:"Do I need the medical before my cabin crew course?",a:"You need it before you apply for your cabin crew licence. Many schools ask for it at the start of the course, so check with your school."},{q:"Are height and swimming part of the medical?",a:"No. Height, reach and swimming requirements in cabin crew adverts are set by airlines and schools. The medical certificate covers medical fitness under Part 67."}],sources:[e.cabin,e.classes,e.faq,e.class4,e.duties,e.protocols,e.avmed,e.register]},l={slug:"aviation-medical-midrand-johannesburg",title:"Aviation Medical in Midrand and Johannesburg: What to Bring, Time and Cost | ClinoTrend",h1:"Aviation medical in Midrand and Johannesburg: what to bring, how long it takes and what it costs",description:"Planning an aviation medical near Johannesburg, Pretoria or Centurion? Where to go at Grand Central Airport in Midrand, what to bring, how long it takes, what affects the cost and how to fly in.",excerpt:"Where to go at Grand Central Airport, the checklist to bring, how long to allow, what affects the cost and how to fly in.",keyword:"aviation medical examiner johannesburg",question:"Where can I get an aviation medical near Johannesburg, and what does it involve?",answer:"Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336), does Class 2 and Class 4 medicals at Gate 2, Grand Central Airport, Midrand, on the N1 between Johannesburg and Pretoria. Bring your ID, licence, current certificate and a list of your medicines. Allow 30 to 60 minutes. Aviation medicals start from R1,500.",secondary:["aviation medical midrand","what to bring to aviation medical","how long does an aviation medical take","aviation medical cost","aviation medical near me"],published:"2026-10-23",updated:"2026-10-29",status:"draft",tag:"Local guide",body:[{t:"p",x:"Most pilots and cabin crew in Gauteng look for an aviation medical that is easy to reach from home, the flight school or the airfield. Grand Central Airport in Midrand sits on the N1 between Johannesburg and Pretoria, which makes it a practical stop for both. This guide covers who can be examined at ClinoTrend, what to bring, how long it takes and what goes into the cost."},{t:"h2",x:"Which medicals are done at Grand Central?",id:"which"},{t:"p",x:"Dr A.O. Ndhlovu is listed by SACAA as a Regular Designated Aviation Medical Examiner, number MR 336. SACAA authorises Regular DAMEs to examine for and issue Class II and Class IV certificates."},{t:"table",caption:"Medical classes at ClinoTrend (SACAA Part 67)",head:["Class","Who it is for","At ClinoTrend"],rows:[["Class 2","Student pilots (SPL) and private pilots (PPL), plus other licences listed in regulation 67.00.2","Yes"],["Class 4","Cabin crew, and recreational pilots such as microlight, gyroplane, glider and free balloon pilots","Yes"],["Class 1","Commercial and airline transport pilots","No, Senior DAMEs only"],["Class 3","Air traffic controllers","No, Senior DAMEs only"]]},{t:"p",x:"If you are not sure which class you need, ask when you book. Cabin crew can read more in our [cabin crew Class 4 guide](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"Where to go",id:"where"},{t:"p",x:"ClinoTrend Health & Aviation is in the **Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand**."},{t:"ul",items:["**From Johannesburg and Sandton:** take the N1 north, exit at New Road or Allandale and follow New Road to Grand Central Airport.","**From Pretoria and Centurion:** take the N1 south to the New Road or Allandale exit, then follow New Road to the airport.","**By Gautrain:** Midrand Gautrain Station is about 5 minutes away by e-hailing or taxi.","**Parking:** boom-gated parking at the terminal. Go to Gate 2.","**Flying in:** Grand Central is FAGC. The apron and visitor aircraft parking are directly outside the Gate 2 terminal doors, so you can combine your medical with a flight."]},{t:"p",x:"Pilots also come from airfields such as Lanseria, Wonderboom and Rand Airport, and patients from Randburg, Kempton Park and Germiston."},{t:"h2",x:"What to bring",id:"bring"},{t:"p",x:"Part 67 (regulation 67.00.7) requires you to show proof of identity, your licence and your latest medical certificate if you have one, give your medical history and sign a declaration. Bring:"},{t:"ul",items:["Your South African ID, driving licence or passport","Any aviation licence you hold (pilot or cabin crew)","Your most recent aviation medical certificate, if you have one","Your logbook, if you are a pilot renewing","A list of every medicine you take, including over the counter medicines and supplements","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist for any medical condition","Your medical aid card, if applicable"]},{t:"p",x:"You can look at the SACAA [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02(a).pdf) beforehand to see which history questions you will be asked."},{t:"h2",x:"How long does an aviation medical take?",id:"time"},{t:"p",x:"Allow about **30 to 60 minutes**, and arrive 10 minutes early to complete paperwork. The time depends on whether this is your first medical or a renewal, on your medical history and on whether you bring all your documents."},{t:"p",x:"The examination covers your history, a physical examination and on-site tests: a resting ECG, vision testing, a hearing test (audiometry) and urine screening. If you meet the standards and no further reports are needed, the certificate can be issued at the end of the examination. If more information is needed, we explain the next steps before you leave."},{t:"h2",x:"What does an aviation medical cost?",id:"cost"},{t:"p",x:"Fees differ between examiners and are set by each practice, so compare like with like. At ClinoTrend, aviation medicals start from R1,500. What to know about the fee:"},{t:"ul",items:["**Extra tests or reports.** Only if the doctor finds during your medical that they are needed, for example blood tests, X-rays or specialist reports. Some are done and billed by another provider.","**Medical aid.** Cover differs between plans, so check with your scheme and with us before your visit."]},{t:"confirm",x:"Please confirm the fee line (from R1,500, extra tests added only when needed, as on the live site) and the 30 to 60 minutes. Also confirm the Midrand Gautrain Station time (about 5 minutes by e-hailing or taxi)."},{t:"h2",x:"Hours and booking",id:"hours"},{t:"p",x:`${i} Closed on weekends and public holidays. Book online, call ${t.display} or WhatsApp ${o.display}; ask about the fee at the same time. Renewing? Read [how to renew your Class 2 medical](/blog/renew-sacaa-class-2-medical/) and check your dates with our [validity guide and calculator](/blog/class-2-medical-validity-by-age/). The full checklist is on the [aviation medicals page](/aviation-medicals/).`},{t:"cta",x:"Book your aviation medical at Gate 2, Grand Central Airport."}],faq:[{q:"Where can I get an aviation medical near Johannesburg?",a:"Dr A.O. Ndhlovu, a SACAA Regular DAME (MR 336), examines pilots and cabin crew at ClinoTrend Health & Aviation, Gate 2, Grand Central Airport, Midrand, on the N1 between Johannesburg and Pretoria."},{q:"How long does an aviation medical take?",a:"Allow about 30 to 60 minutes, and arrive 10 minutes early for paperwork."},{q:"How much does an aviation medical cost in Midrand?",a:"At ClinoTrend, aviation medicals start from R1,500. If the doctor finds during your medical that extra tests or reports are needed, these are added to the fee."},{q:"Can I do a Class 1 medical at ClinoTrend?",a:"No. Class 1 and Class 3 medicals need a SACAA Senior DAME. ClinoTrend does Class II and Class IV."},{q:"Can I fly in to Grand Central for my medical?",a:"Yes. Grand Central is FAGC, and the apron and visitor aircraft parking are outside the Gate 2 terminal doors, next to the practice."}],sources:[e.register,e.avmed,e.classes,e.application,e.form,e.faq]},d={slug:"class-2-medical-validity-by-age",title:"How Long Is a Class 2 Medical Valid? SACAA Validity by Age | ClinoTrend",h1:"How long is a Class 2 medical valid? SACAA validity by age",description:"SACAA Class 2 and Class 4 medical validity by age, as published by SACAA: Class 2 is 24 months under 40 and 12 months over 40, Class 4 is 60 and 36 months. How the date is counted, plus an expiry calculator.",excerpt:"The SACAA validity periods for Class 2 and Class 4 by age, how the expiry date is counted, and a calculator to check yours.",keyword:"how long is a class 2 medical valid for",question:"How long is a SACAA Class 2 or Class 4 medical valid?",answer:"SACAA's published table gives a Class 2 medical 24 months if you are under 40 and 12 months over 40. A Class 4, which covers cabin crew and most recreational pilots, is valid for 60 months under 40 and 36 months over 40. Certificates run to the last day of the month, and a medical condition can mean a shorter period.",secondary:["class 2 medical over 40","class 2 medical duration","how long does an aviation medical certificate last","class 4 medical certificate south africa"],published:"2026-10-23",updated:"2026-10-29",status:"draft",tag:"Validity",body:[{t:"p",x:"How long your SACAA medical lasts depends on two things: the class of the certificate and your age. The South African Civil Aviation Authority sets out the periods in the medical requirements table on its frequently asked questions page. This guide puts those periods in one place, shows how the expiry date is worked out and gives you a calculator to check your own date."},{t:"h2",x:"The short answer",id:"answer"},{t:"table",caption:"Validity of SACAA medical certificates (SACAA frequently asked questions)",head:["Class","Who it covers","Under 40","Over 40"],rows:[["Class 2","Student and private pilots","24 months","12 months"],["Class 4","Cabin crew, and recreational pilots such as microlight, glider, gyroplane and free balloon","60 months","36 months"]]},{t:"p",x:"Cabin crew sit under Class 4: SACAA's FAQ confirms that cabin crew have needed a Class 4 medical since the regulation was promulgated in May 2019. So a private pilot under 40 renews every two years, and every year once over 40. A cabin crew member or a microlight pilot under 40 renews every five years, and every three years once over 40."},{t:"p",x:"For reference, SACAA lists Class 1 (airline transport and commercial pilots) at 12 months, with 6 months for airline transport pilots over 40 and for commercial pilots over 60. Class 1 and Class 3 are done by Senior DAMEs, not at this practice."},{t:"confirm",x:"The periods above follow the SACAA FAQ page (Ruben's decision, 23 Oct 2026). Part 67 regulation 67.00.6(3), as amended in May 2017, and the SACAA Summarised Medical Protocols (Nov 2021) give Class 2 as 60 months under 40, 24 months over 40 and 12 months over 50. Please confirm which periods you issue in practice so the site matches your certificates."},{t:"h2",x:"How the expiry date is counted",id:"counting"},{t:"p",x:"Certificates run to the **last day of a month**, not to the day of your examination. SACAA's FAQ notes that its EMPIC system does not do this automatically, so the examiner sets the date to the last day of the month before printing the certificate. Two examples:"},{t:"ul",items:["A 34 year old student pilot is issued a Class 2 certificate on 10 March 2026. The period is 24 months, so it runs to 31 March 2028.","A 46 year old private pilot is issued a Class 2 certificate on 10 March 2026. The period is 12 months, so it runs to 31 March 2027."]},{t:"p",x:"The date printed on your certificate is the one that counts. Use the calculator below as a guide only."},{t:"calc"},{t:"h2",x:"When you need medicals more often",id:"shorter"},{t:"p",x:"The SACAA table adds that the frequency of examinations may also vary depending on medical conditions affecting the applicant. For example, a condition that needs regular review can mean a certificate with a shorter period, or a request for reports in between. Your certificate shows the period and any limitation that applies to you."},{t:"p",x:"If you have a condition or take regular medicine, tell us when you book. That gives you time to bring the right reports and avoid a second visit."},{t:"h2",x:"Turning 40",id:"birthdays"},{t:"p",x:"Your 40th birthday is the point where Class 2 drops from 24 to 12 months and Class 4 from 60 to 36 months. SACAA's FAQ also answers how an examiner handles an applicant who is 39 and about to turn 40. The examiner can either issue a certificate for the time left before you turn 40, or issue it with the period that applies from 40."},{t:"p",x:"If your birthday falls close to your renewal, ask about this when you book so you know which date to expect."},{t:"h2",x:"Planning your renewals",id:"planning"},{t:"p",x:"Because the new certificate runs from the month it is issued, renewing many months early does not add the unused time to your new certificate. Booking a few weeks before the expiry date is a sensible plan. It leaves time for a specialist letter or an extra test if one is requested, without a gap in flying or in your cabin crew duties."},{t:"p",x:"A simple habit helps: when you receive a new certificate, put a reminder in your calendar six weeks before the date printed on it. SACAA lists a chest X-ray at the initial examination and afterwards only when it is indicated on clinical grounds, so most renewals need less than a first medical. At ClinoTrend, a resting ECG, vision testing, a hearing test and urine screening are done on site. If your age or history means you need a test that is not done here, we tell you when you book."},{t:"h2",x:"Close to expiry?",id:"extension"},{t:"p",x:"SACAA's FAQ says requests for an extension on a medical go to its aviation medicine department. Part 67, regulation 67.00.6(6), says to apply at least 15 days before the certificate expires, and an extension is for no more than 30 days. An extension is a safety net, not a plan. Our step by step [Class 2 renewal guide](/blog/renew-sacaa-class-2-medical/) explains the process, and cabin crew can read the [Class 4 guide](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"p",x:"Dr A.O. Ndhlovu (SACAA MR 336) does Class II and Class IV renewals at Gate 2, Grand Central Airport, Midrand. See the [aviation medicals page](/aviation-medicals/) for what to bring and how the examination works."},{t:"cta",x:"Medical expiring soon? Book your renewal."}],faq:[{q:"How long is a Class 2 medical valid if I am under 40?",a:"SACAA lists 24 months for Class 2 holders under 40. The certificate runs to the last day of the month."},{q:"How long is a Class 2 medical valid over 40?",a:"SACAA lists 12 months for Class 2 holders over 40, so most private pilots over 40 renew every year."},{q:"How long is a Class 4 medical valid?",a:"60 months under 40 and 36 months over 40, according to the SACAA medical requirements table."},{q:"Can my certificate be valid for a shorter time?",a:"Yes. SACAA notes that the frequency of examinations may vary depending on medical conditions. The period on your certificate is the one that applies."},{q:"Can I extend my medical certificate?",a:"Contact the SACAA aviation medicine department before your certificate expires. The SACAA FAQ page explains where to send the request."}],sources:[e.faq,e.validityReg,e.am007,e.classes,e.avmed]},c={slug:"sacaa-medical-classes-explained",title:"SACAA Medical Classes Explained: Class 1, 2, 3, 4 and 5 | ClinoTrend",h1:"SACAA medical classes explained: which aviation medical do you need?",description:"Which SACAA medical certificate you need for your licence: Class 1 for commercial pilots, Class 2 for student and private pilots, Class 3 for air traffic services, Class 4 for cabin crew and recreational pilots, and Class 5.",excerpt:"A plain guide to the five SACAA medical classes, which licences each one covers, who may examine you and how one class can cover another.",keyword:"aviation medical classes",question:"Which SACAA medical class do I need for my licence?",answer:"It depends on your licence. Under Part 67, regulation 67.00.2, commercial and airline pilots need a **Class 1**, student and private pilots a **Class 2**, air traffic services staff a **Class 3**, cabin crew and most recreational pilots a **Class 4**, and paragliding, hang gliding and parachute licences a **Class 5** declaration. ClinoTrend does Class 2 and Class 4 medicals.",secondary:["class 1 vs class 2 medical","class 1 medical certificate south africa","what is a class 2 medical","sacaa medical requirements","sacaa medical certificate"],published:"2026-10-29",updated:"2026-10-29",status:"draft",tag:"Medical classes",body:[{t:"p",x:"Every South African pilot, air traffic controller and cabin crew member needs a medical certificate issued under Part 67 of the Civil Aviation Regulations. Part 67 sorts licences into five medical classes. The class sets who may examine you, how strict the standards are and how often you renew. This guide explains each class in plain language, quoting the regulation where it matters."},{t:"h2",x:"What are the five SACAA medical classes?",id:"classes"},{t:"table",caption:"SACAA medical classes (Part 67, regulation 67.00.2, as amended)",head:["Class","Main licences it covers","Who examines"],rows:[["Class 1","Airline transport pilot (ATPL), commercial pilot (CPL) for aeroplane, airship and helicopter, instrument rating, Class I test pilot rating","Senior DAME"],["Class 2","Student pilot (SPL), private pilot (PPL) for aeroplane, airship and helicopter, flight engineer, free balloon CPL, commercial glider pilot","Regular or Senior DAME"],["Class 3","Air traffic controller (ATC), air traffic service assistant, remote pilot (RPL)","Senior DAME"],["Class 4","Cabin crew member licence, microlight, gyroplane, light sport aeroplane, glider and non commercial free balloon licences, and their student licences","Any HPCSA registered doctor, or a DAME"],["Class 5","Paraglider, hang glider, powered paratrike and parachute licences and their student licences","Self declaration"]]},{t:"p",x:"The table shortens the lists. The full wording is in the [SACAA copy of regulation 67.00.2](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf), which also lists instructor ratings, tandem licences and test pilot ratings."},{t:"h2",x:"What is the difference between a Class 1 and a Class 2 medical?",id:"class-1-vs-2"},{t:"p",x:"A Class 1 is for flying as a profession: the CPL, the ATPL and the instrument rating. A Class 2 is for the student and private pilot licences, among others. Class 1 certificates are renewed more often, and the examination must be done by a SACAA **Senior** Designated Aviation Medical Examiner (DAME)."},{t:"p",x:"Regulation 67.00.2(2) adds a useful rule: a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates. If you stop flying commercially, regulation 67.00.2(4) lets you ask for an expired Class 1 to be substituted by a Class 2 or Class 4 for the rest of the period it would have been valid as that class."},{t:"h2",x:"Which class do cabin crew need?",id:"cabin-crew"},{t:"p",x:"The amended regulation lists the cabin crew member licence under **Class 4**. Our [cabin crew medical guide](/blog/cabin-crew-medical-class-4-south-africa/) explains what that means in practice, including why some older SACAA pages still show Class II for cabin crew."},{t:"h2",x:"Which class do recreational pilots need?",id:"recreational"},{t:"p",x:"Most recreational licences are Class 4: microlight, gyroplane, light sport aeroplane, touring motor glider, non commercial glider and free balloon, plus the matching student licences. Paragliding, hang gliding and parachuting sit in Class 5, which works on a self declaration sent to SACAA. Regulation 67.00.2(8) and (9) say a person aged 60 or older needs the Class 5 declaration signed by a registered doctor."},{t:"p",x:"One detail is easy to miss. Regulation 67.00.2(7) says a Class 4 holder who flies **above 12 000 ft** must meet the respiratory and lung function test requirements of a Class 2."},{t:"h2",x:"Who can examine you for each class?",id:"who"},{t:"p",x:"SACAA designates two kinds of aviation medical examiners. A **Regular DAME** may examine for and issue Class II and Class IV certificates. A **Senior DAME** may also do Class I and Class III. For a Class 4, regulation 67.00.5 also allows any doctor registered with the HPCSA to do the examination. Read [how to find and check a SACAA medical examiner](/blog/sacaa-medical-examiners-dame/) for more."},{t:"p",x:"Dr A.O. Ndhlovu is a SACAA Regular DAME (MR 336). At ClinoTrend, Gate 2, Grand Central Airport, he does **Class 2 and Class 4** medicals. Class 1 and Class 3 medicals are done by Senior DAMEs."},{t:"h2",x:"How long is each certificate valid?",id:"validity"},{t:"p",x:"Validity depends on the class and on your age, and certificates run to the last day of a month. Class 2 and Class 4 periods, with a small expiry calculator, are in [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/). For Class 1 and Class 3, ask your Senior DAME or read regulation 67.00.6."},{t:"confirm",x:'This post keeps validity numbers out on purpose and links to the validity guide, which follows the SACAA FAQ (Ruben, 23 Oct). Please confirm you are happy with the class table and the "Who examines" column, in particular that Class 3 needs a Senior DAME.'},{t:"h2",x:"Not sure which class you need?",id:"unsure"},{t:"p",x:"Check the licence you hold or plan to apply for, then find it in the table above. If you are a student pilot who plans to fly commercially later, read our [student pilot medical guide](/blog/student-pilot-medical-south-africa/). If you are still unsure, ask us when you book, call 011 568 7979 or WhatsApp 078 255 1405, and we will confirm the class before your appointment."},{t:"cta",x:"Need a Class 2 or Class 4 medical? Book at Gate 2, Grand Central Airport."}],faq:[{q:"Do private pilots need a Class 1 or a Class 2 medical?",a:"A Class 2. Regulation 67.00.2 lists the student pilot licence and the private pilot licence for aeroplane, airship and helicopter under Class 2."},{q:"Does a Class 1 medical cover Class 2?",a:"Yes. Regulation 67.00.2(2) says a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates."},{q:"Which medical class do air traffic controllers need?",a:"Class 3. It also covers air traffic service assistants and remote pilots (RPL). Class 3 medicals are done by a SACAA Senior DAME."},{q:"Can a Regular DAME do a Class 1 medical?",a:"No. A Regular DAME does Class II and Class IV. Class I and Class III need a Senior DAME."},{q:"What is a Class 5 medical?",a:"A self declaration for paragliding, hang gliding, powered paratrike and parachute licences, sent to SACAA. From age 60 it must be signed by a registered doctor."}],sources:[e.classes,e.classesReg,e.class4,e.validityReg,e.avmed,e.register]},h={slug:"student-pilot-medical-south-africa",title:"Student Pilot Medical in South Africa: What You Need Before You Fly Solo | ClinoTrend",h1:"Student pilot medical in South Africa: what you need before you fly solo",description:"Starting flight training in South Africa? Which SACAA medical a student pilot needs, when to get it, what the first medical involves, what to bring and how flight schools can book group medicals in Midrand.",excerpt:"Which medical a student pilot needs, when to book it, what the first examination involves and what to bring. For new students, parents and flight schools.",keyword:"student pilot medical requirements",question:"What medical does a student pilot need in South Africa?",answer:"To be issued a student pilot licence (SPL) you must be at least 15, be registered with an approved training organisation (ATO) and hold a valid Part 67 medical certificate. For an aeroplane or helicopter SPL that is a **Class 2** medical, done by a SACAA designated examiner. Book it early in your training, before you need your SPL.",secondary:["student pilot medical certificate","flight school medical requirements","first class 2 medical","does student pilot need medical","what medical certificate for private pilot"],published:"2026-10-29",updated:"2026-10-29",status:"draft",tag:"Student pilots",body:[{t:"p",x:"A first aviation medical is one of the early steps in learning to fly. It is also a step that can hold up training if it is left late. This guide is for new student pilots, their parents and the flight schools that train them. It explains which certificate you need, when to get it and what happens at the first examination."},{t:"h2",x:"Do student pilots need a medical?",id:"need"},{t:"p",x:"Yes. Part 61, regulation 61.02.1 (as amended on 21 August 2026), says an applicant for a student pilot licence (SPL) or integrated student pilot licence (ISPL) must be 15 years or older, hold a valid medical certificate issued in terms of Part 67, and be registered with an approved training organisation (ATO). Your SPL is what allows you to fly solo under instruction, so the medical comes first."},{t:"h2",x:"Which medical class does a student pilot need?",id:"class"},{t:"p",x:"Regulation 67.00.2 lists the SPL under **Class 2**, alongside the private pilot licence (PPL). Students on recreational licences are different: an SPL for a microlight, gyroplane, light sport aeroplane or glider licence sits under **Class 4**. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) has the full list."},{t:"confirm",x:"The 21 August 2026 amendment added the integrated student pilot licence (ISPL). Please confirm which medical class SACAA expects for ISPL students in integrated (commercial) training, so we can state it plainly here."},{t:"h3",x:"Planning to fly commercially?"},{t:"p",x:"A commercial pilot licence (CPL), an airline transport pilot licence (ATPL) and an instrument rating all need a **Class 1** medical, which only a SACAA Senior DAME may do. Ask your flight school when it wants you to hold a Class 1. Dr Ndhlovu is a Regular DAME, so at ClinoTrend we do the Class 2 that covers your SPL and PPL, not the Class 1."},{t:"h2",x:"When should I book my first medical?",id:"when"},{t:"p",x:"Book it before your first solo is close, ideally when you sign up with your flight school. A first medical sometimes needs an extra report, for example from an optometrist, or a test that is not done on the day. Booking early leaves time for that without holding up your training. Your flight school will tell you when it needs to see your certificate."},{t:"h2",x:"What happens at a first Class 2 medical?",id:"exam"},{t:"p",x:"You complete your medical history on the SACAA form and sign a declaration that it is accurate, complete and true, as regulation 67.00.7 requires. The doctor then examines you. At ClinoTrend these tests are done on site:"},{t:"ul",items:["Resting ECG","Vision testing","Hearing test (audiometry)","Urine screening"]},{t:"p",x:"SACAA's medical requirements list a chest X-ray at the initial examination, and afterwards only when it is indicated on clinical grounds. If your first medical needs anything that is not done on site, we tell you when you book. Allow about 30 to 60 minutes."},{t:"confirm",x:"Please confirm the tests for a first Class 2 at ClinoTrend (chest X-ray at initial, any lung function test or bloods) and whether the X-ray is referred out, so the wording matches what students will experience."},{t:"h2",x:"What should a student pilot bring?",id:"bring"},{t:"ul",items:["Your South African ID or passport","Glasses or contact lenses, and a recent optometrist prescription if you have one","A list of every medicine you take, including over the counter medicines and supplements","Reports from your doctor or specialist for any medical condition, past operation or hospital stay","Any letter or form from your flight school"]},{t:"p",x:"You can read the SACAA [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02(a).pdf) beforehand to see the history questions. Be complete and honest. If something needs a report, it is much easier to sort out before the examination than after."},{t:"h3",x:"Under 18?"},{t:"p",x:"Students can start from 15. If you are under 18, a parent or guardian is welcome to come with you and can help with your medical history."},{t:"confirm",x:"Please confirm the practice's rule for patients under 18 (parent or guardian present, consent form) so this line is accurate."},{t:"h2",x:"How long is a student pilot's Class 2 valid?",id:"validity"},{t:"p",x:"It depends on your age, and the certificate runs to the last day of a month. Most student pilots are under 40. See [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) for the periods SACAA publishes and a calculator to work out your date."},{t:"h2",x:"Group medicals for flight schools",id:"groups"},{t:"p",x:`ClinoTrend is in the Main Terminal Building at Grand Central Airport (FAGC), Gate 2, so students training at Grand Central can walk over between lessons. Flight schools, cabin crew academies and airlines can arrange group bookings in advance: call 011 568 7979 or email ${n} with the number of students and the dates that suit you.`},{t:"cta",x:"Starting flight training? Book your first Class 2 medical."}],faq:[{q:"Do I need a medical before my first flying lesson?",a:"You need a valid Part 67 medical certificate to be issued a student pilot licence, which you need before you fly solo. Ask your flight school when it wants to see it; many students book the medical when they sign up."},{q:"What medical class is a student pilot licence?",a:"Class 2 for the aeroplane, airship and helicopter SPL. A student licence for a microlight, gyroplane, light sport aeroplane or glider sits under Class 4."},{q:"How old must I be for a student pilot licence?",a:"15 or older, according to Part 61, regulation 61.02.1."},{q:"Can I do my Class 1 medical at ClinoTrend?",a:"No. A Class 1 needs a SACAA Senior DAME. Dr Ndhlovu is a Regular DAME and does Class 2 and Class 4 medicals."},{q:"Can a flight school book medicals for a group of students?",a:"Yes. Group bookings for flight schools are arranged in advance. Call 011 568 7979 with the number of students and the dates that suit you."}],sources:[e.spl,e.classes,e.application,e.protocols,e.form,e.avmed,e.register]},u={slug:"sacaa-medical-examiners-dame",title:"SACAA Medical Examiners: How to Find and Check a DAME | ClinoTrend",h1:"SACAA medical examiners: how to find and check a designated examiner (DAME)",description:"What a SACAA Designated Aviation Medical Examiner (DAME) is, the difference between a Regular and a Senior DAME, how to check that an examiner is on the SACAA list and where to find one in Midrand.",excerpt:"What a DAME is, Regular versus Senior, how to check an examiner on the SACAA list before you book, and why it matters.",keyword:"sacaa medical examiners",question:"How do I find a SACAA approved aviation medical examiner, and check that they are designated?",answer:"Aviation medicals for Class 1, 2 and 3 must be done by a SACAA Designated Aviation Medical Examiner (DAME). SACAA publishes lists of Regular DAMEs (Class II and IV) and Senior DAMEs (Class I to IV) on its aviation medicine page. Check that your examiner is on the current list, and for the right class, before you book.",secondary:["sacaa approved medical examiner","sacaa medical examiners contact details","sacaa medical doctors","aviation medical examiner south africa","aviation medical near me"],published:"2026-10-29",updated:"2026-10-29",status:"draft",tag:"Examiners",body:[{t:"p",x:"Your medical certificate is only as good as the examiner who issued it. This guide explains what a Designated Aviation Medical Examiner is, which examiner can do which class, and how to check an examiner yourself in a couple of minutes."},{t:"h2",x:"What is a DAME?",id:"what"},{t:"p",x:"A DAME is a doctor designated by the Director of Civil Aviation to do the medical examinations and tests needed for SACAA medical certificates. Regulation 67.00.4 of Part 67 says the Director signs and issues each DAME a document that names the examiner and states that he or she may examine applicants, issue the certificate, or defer it until SACAA gives an instruction."},{t:"p",x:'People often search for a "SACAA approved" or "SACAA accredited" doctor. The term the regulations use is **designated**.'},{t:"h2",x:"Regular DAME or Senior DAME: what is the difference?",id:"regular-senior"},{t:"table",caption:"SACAA examiner categories",head:["Examiner","Classes","Typical licences"],rows:[["Regular DAME","Class II and Class IV","Student and private pilots, cabin crew, recreational pilots"],["Senior DAME","Class I, II, III and IV","Also commercial and airline pilots and air traffic services"]]},{t:"p",x:"A Class 4 medical is the exception to the DAME rule: regulation 67.00.5 lets any doctor registered with the HPCSA do the examination, with the application and results sent to SACAA for verification within 60 days. Not sure which class you need? See [SACAA medical classes explained](/blog/sacaa-medical-classes-explained/)."},{t:"h2",x:"How do I check that an examiner is designated?",id:"check"},{t:"ol",items:["Open the [SACAA aviation medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) and find the lists of Regular and Senior Designated Aviation Medical Examiners.","Search the list for the doctor's name. Each entry shows a designation code, the practice address, the area and contact details.","Check the category: a Regular DAME is listed for Class II and IV only.","At your appointment you can ask to see the designation certificate. SACAA procedure AM007 says a DAME must have proof of designation, a certificate showing its period of validity, at the practice."]},{t:"h2",x:"Why it matters",id:"why"},{t:"p",x:"A designation has a validity period and can lapse. In 2024 SACAA published a notice about certificates issued by an examiner whose designation had lapsed, and asked the licence holders concerned to be examined again because those certificates were not valid. A quick check before you book avoids that risk."},{t:"confirm",x:"The 2024 SACAA notice is cited from the earlier research (general notice of 10 Sep 2024) but the caa.co.za page could not be opened from our side today. Please confirm you are comfortable mentioning it, or we remove the paragraph."},{t:"h2",x:"Finding a SACAA medical examiner in Midrand",id:"midrand"},{t:"p",x:"Dr A.O. Ndhlovu is on the SACAA list of Regular Designated Aviation Medical Examiners as **MR 336**, at ClinoTrend Health & Aviation, Grand Central Airport, Midrand, telephone 011 568 7979. He examines for Class II and Class IV: student and private pilots, cabin crew and recreational pilots."},{t:"p",x:"The practice is in the Main Terminal Building, Gate 2, Office TG6B, on the N1 between Johannesburg and Pretoria. You can also fly in to FAGC. For directions, what to bring and how long to allow, read our [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/) or the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book your Class 2 or Class 4 medical with Dr Ndhlovu (MR 336)."}],faq:[{q:"What does DAME stand for?",a:"Designated Aviation Medical Examiner: a doctor designated by the Director of Civil Aviation under Part 67, regulation 67.00.4, to do aviation medical examinations and issue or defer SACAA medical certificates."},{q:"Where is the list of SACAA medical examiners?",a:"On the SACAA aviation medicine page, which links to the lists of Regular and Senior Designated Aviation Medical Examiners with their codes, areas and contact numbers."},{q:"Can a Regular DAME renew my Class 2?",a:"Yes. Regular DAMEs examine for and issue Class II and Class IV certificates. Class I and Class III need a Senior DAME."},{q:"Can my own GP do my aviation medical?",a:"For Class 1, 2 and 3, only if your GP is a SACAA designated examiner for that class. For a Class 4, any HPCSA registered doctor may do the examination."},{q:"Is Dr Ndhlovu a SACAA designated examiner?",a:"Yes. Dr A.O. Ndhlovu is listed by SACAA as a Regular Designated Aviation Medical Examiner, MR 336, at Grand Central Airport, Midrand."}],sources:[e.register,e.avmed,e.designation,e.class4,e.am007,e.classes]},m={slug:"aviation-medical-deferred-what-next",title:"Aviation Medical Deferred or Not Issued? What Happens Next | ClinoTrend",h1:"Aviation medical deferred or not issued: what happens next?",description:"What it means when a SACAA aviation medical is deferred, referred to the Aeromedical Committee or issued with a limitation, how long the process can take, how to appeal and what to report between medicals.",excerpt:"What a deferral means, how SACAA reviews a case, limitations and shorter validity, the 30 day appeal, and what you must report between medicals.",keyword:"aviation medical deferral",question:"What happens if my SACAA aviation medical is deferred or I do not meet the standard?",answer:'A deferral is not a final "no". Under Part 67 a designated examiner may defer your certificate until SACAA gives an instruction, usually once a specialist report or extra test is in. Complicated cases go to the SACAA Aeromedical Committee. A certificate can also be issued with a limitation or a shorter validity, and you may appeal a decision within 30 days.',secondary:["failed aviation medical","sacaa medical requirements","sacaa medical protocols","aeromedical committee","flying on medication"],published:"2026-10-29",updated:"2026-10-29",status:"draft",tag:"Next steps",body:[{t:"p",x:"Most aviation medicals end with a certificate on the day. Sometimes the examiner needs more information first. That can be worrying, especially if your training, your job or a check ride depends on it. This guide explains, step by step, what the regulations say happens next, so you know what to expect and what you can do."},{t:"h2",x:"What does a deferred medical mean?",id:"deferred"},{t:"p",x:"Part 67, regulation 67.00.4, says a designated examiner may examine you, issue your certificate, or **defer** it pending an instruction from SACAA. A deferral means the examiner cannot decide on the day, usually because a finding or something in your history needs more information. It is not the same as being declared unfit."},{t:"p",x:"The SACAA medical protocols list, condition by condition, the reports SACAA wants. Many ask for a recent specialist report, often not older than three months, and some ask for a test such as a stress ECG or a lung function test."},{t:"h2",x:"What happens after a deferral?",id:"process"},{t:"ol",items:["The examiner explains what is needed, for example a specialist report, a test result or records from your own doctor.","You arrange the report or test and send it to the examiner.","Straightforward cases can then be finalised. SACAA procedure AM007 says complicated cases are referred to the SACAA **Aeromedical Committee (AMC)**, an advisory panel of medical and aviation industry experts.","The AMC meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting."]},{t:"p",x:"Time matters here. Regulation 67.00.12 says the records of a medical examination may be used to issue a certificate for no more than **90 days**. If your reports take longer than that, the examination may have to be repeated."},{t:"h2",x:"Can I get a certificate with a limitation?",id:"limitation"},{t:"p",x:"Yes. Part 67 allows a certificate to be endorsed with a requirement or limitation when safe flying depends on it, for example wearing corrective lenses. Regulation 67.00.6(5) also lets the examiner or SACAA's medical assessor shorten the validity period, for instance so that a condition is reviewed more often."},{t:"p",x:"Regulation 67.00.8(4A) goes further. In exceptional circumstances SACAA's medical assessor may issue or renew a certificate for someone who does not meet some of the standards, if accredited medical conclusion shows that flying is not likely to jeopardise safety, taking account of the person's ability, skill, experience and operating conditions. Any limitation that safety depends on is endorsed on the licence."},{t:"h2",x:"Can I appeal a decision?",id:"appeal"},{t:"p",x:"Yes. SACAA procedure AM007 says applicants who are aggrieved by the decision of a designated examiner, an authorised officer or the designated body may appeal to the Director of Civil Aviation within **30 days**, as prescribed in Part 67. If SACAA suspends a certificate, regulation 67.00.14 sets a shorter period: an appeal within 14 days of the suspension."},{t:"h2",x:"What must I report between medicals?",id:"between"},{t:"p",x:"Your duties do not stop at the examination. Regulation 67.00.9 says you may not act as a pilot, air traffic service member or cabin crew member while you know of a medical condition or medicine that could affect your certificate, or once it has expired. You must also tell SACAA without undue delay about any:"},{t:"ul",items:["Injury or hospital stay","Operation or invasive procedure","Regular use of medicine","Pregnancy","Illness that keeps you off duty for more than 21 days","Psychiatric treatment"]},{t:"p",x:"That applies where the event means you no longer meet the medical standards. Before you fly again you must give SACAA proof that you have fully recovered. If you are unsure whether something counts, ask your examiner. AM007 says every applicant is responsible for consulting their DAME about medical conditions or medicines being considered, to make sure they are compatible with flying."},{t:"h2",x:"How to keep a deferral short",id:"tips"},{t:"ul",items:["Tell us about any condition, operation or regular medicine when you book, so you can bring the right reports on the day.","Bring recent reports from your doctor or specialist, not only a referral letter.","Answer the history questions on the SACAA form fully. You sign a declaration that they are accurate, complete and true.","Keep copies of everything you send, and note the AMC dates if your case is referred."]},{t:"p",x:"If your medical at ClinoTrend cannot be finalised on the day, Dr Ndhlovu explains the next steps before you leave. See the [aviation medicals page](/aviation-medicals/) for how the examination works and our [renewal guide](/blog/renew-sacaa-class-2-medical/) for planning your next one."},{t:"confirm",x:'Please check the tone and the steps in "What happens after a deferral?" against how you handle deferrals in practice (who sends reports to SACAA, typical waiting time). No timelines are promised in the post.'},{t:"cta",x:"Have a condition or regular medicine? Tell us when you book."}],faq:[{q:"Does a deferred medical mean I failed?",a:"No. A deferral means the examiner needs more information, such as a specialist report or a test, before the certificate can be issued. SACAA then decides, sometimes with advice from its Aeromedical Committee."},{q:"When does the SACAA Aeromedical Committee meet?",a:"SACAA procedure AM007 says the committee meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting."},{q:"How long are my medical examination results valid for?",a:"Regulation 67.00.12 says examination records may be used to issue a certificate for no more than 90 days. After that the examination may need to be repeated."},{q:"How long do I have to appeal a medical decision?",a:"SACAA procedure AM007 says you may appeal to the Director of Civil Aviation within 30 days. An appeal against a suspension must be made within 14 days, under regulation 67.00.14."},{q:"Can I fly while taking medicine?",a:"Not while you know of a medicine or condition that could affect your certificate. Regulation 67.00.9 also requires you to report regular use of medicine. Ask your DAME before you fly."}],sources:[e.designation,e.am007,e.protocols,e.records,e.validityReg,e.issuing,e.suspension,e.duties,e.application]},f=[s,r,l,d,u,c,h,m],A=a=>`/blog/${a.slug}/`,y=[{name:"Home",path:"/"},{name:"Blog",path:"/blog/"}];export{y as B,f as P,A as p};
